import React, { useState } from 'react';
import { 
  Plus, 
  ArrowDownLeft, 
  ArrowUpRight, 
  Box, 
  AlertCircle, 
  Search,
  MoreVertical,
  Maximize2,
  Scan,
  Download,
  X,
  RefreshCw,
  History
} from 'lucide-react';
import { MOCK_PRODUCTS } from '../data/mockData';
import { Product, AdjustmentReason } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<Product[]>(MOCK_PRODUCTS);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [isAdjustModalOpen, setIsAdjustModalOpen] = useState(false);
  const [adjustmentType, setAdjustmentType] = useState<'ADD' | 'REMOVE'>('ADD');
  const [adjAmount, setAdjAmount] = useState<number>(0);
  const [adjReason, setAdjReason] = useState<AdjustmentReason>(AdjustmentReason.RESTOCK);
  const [searchTerm, setSearchTerm] = useState('');

  const handleAdjustStock = () => {
    if (!selectedProduct || adjAmount <= 0) return;

    const updatedProducts = products.map(p => {
      if (p.id === selectedProduct.id) {
        const newStock = adjustmentType === 'ADD' 
          ? p.stock + adjAmount 
          : Math.max(0, p.stock - adjAmount);
        return { ...p, stock: newStock };
      }
      return p;
    });

    setProducts(updatedProducts);
    setIsAdjustModalOpen(false);
    setSelectedProduct(null);
    setAdjAmount(0);
    // In a real app, we would also save this to a history log table
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const lowStockCount = products.filter(p => p.stock <= p.lowStockThreshold).length;
  const outOfStockCount = products.filter(p => p.stock <= 0).length;
  const totalStockValue = products.reduce((acc, p) => acc + (p.stock * p.priceWholesale), 0);

  return (
    <div className="space-y-6">
      {/* Overview Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-blue-600 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
          <Box className="absolute -right-2 -bottom-2 opacity-10" size={80} />
          <p className="text-blue-100 text-xs font-bold uppercase tracking-wider mb-1">Total SKU</p>
          <p className="text-3xl font-black">{products.length}</p>
          <div className="mt-4 flex items-center gap-1 text-xs font-bold bg-blue-500/30 w-fit px-2 py-1 rounded-full">
            <Plus size={12} />
            Active Catalog
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">Wholesale Value</p>
          <p className="text-3xl font-black text-slate-900">₹{(totalStockValue / 100000).toFixed(2)}L</p>
          <p className="mt-4 text-xs font-medium text-emerald-600 flex items-center gap-1">
            <ArrowUpRight size={14} />
            Updated just now
          </p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">Low Stock</p>
          <p className="text-3xl font-black text-amber-500">{lowStockCount.toString().padStart(2, '0')}</p>
          <p className="mt-4 text-xs font-medium text-slate-500 flex items-center gap-1">
            <AlertCircle size={14} className="text-amber-500" />
            Requires Reorder
          </p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">Out of Stock</p>
          <p className="text-3xl font-black text-red-500">{outOfStockCount.toString().padStart(2, '0')}</p>
          <p className="mt-4 text-xs font-medium text-slate-500">Immediate Action</p>
        </div>
      </div>

      {/* Main Inventory Table */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex flex-col xl:flex-row xl:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <h3 className="font-bold text-lg">Inventory Management</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button className="px-3 py-1 text-xs font-bold bg-white text-blue-600 rounded shadow-sm">Current Stock</button>
              <button className="px-3 py-1 text-xs font-bold text-slate-500 hover:text-slate-700">Stock Logs</button>
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            <div className="relative flex-1 sm:flex-none">
              <Search className="absolute left-3 top-2.5 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Search products..." 
                className="pl-10 pr-4 py-2 bg-slate-50 border-none rounded-xl text-sm w-full md:w-64 focus:ring-2 focus:ring-blue-500"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <button className="bg-slate-100 text-slate-700 px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-slate-200 transition-all border border-slate-200">
              <Scan size={18} />
              Scan
            </button>
            <button className="bg-slate-100 text-slate-700 px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-slate-200 transition-all border border-slate-200">
              <Download size={18} />
              Bulk Import
            </button>
            <button className="bg-blue-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-blue-700 transition-all shadow-md active:scale-95">
              <Plus size={18} />
              Add Product
            </button>
          </div>
        </div>

        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                <th className="px-6 py-4">Item Name</th>
                <th className="px-6 py-4">Category</th>
                <th className="px-6 py-4">Current Stock</th>
                <th className="px-6 py-4">Prices (R | W)</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-center">Quick Adjust</th>
                <th className="px-6 py-4"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredProducts.map(product => (
                <tr key={product.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4">
                    <p className="font-bold text-slate-900 text-sm">{product.name}</p>
                    <p className="text-xs text-slate-400">SKU: VE-{product.id}00X</p>
                  </td>
                  <td className="px-6 py-4">
                    <span className="px-2 py-1 bg-slate-100 text-slate-600 rounded text-[10px] font-bold uppercase tracking-tighter">
                      {product.category}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <span className={`font-black text-sm ${product.stock <= product.lowStockThreshold ? 'text-amber-500' : 'text-slate-900'}`}>
                        {product.stock}
                      </span>
                      <span className="text-xs text-slate-400">pcs</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-xs">
                      <p className="font-bold text-slate-800">₹{product.priceRetail.toLocaleString()}</p>
                      <p className="text-slate-400">₹{product.priceWholesale.toLocaleString()}</p>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${
                      product.stock <= 0 ? 'bg-red-50 text-red-600' :
                      product.stock <= product.lowStockThreshold ? 'bg-amber-50 text-amber-600' :
                      'bg-emerald-50 text-emerald-600'
                    }`}>
                      {product.stock <= 0 ? 'Out of Stock' :
                       product.stock <= product.lowStockThreshold ? 'Low Stock' : 'Healthy'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex justify-center gap-2">
                      <button 
                        onClick={() => {
                          setSelectedProduct(product);
                          setAdjustmentType('ADD');
                          setIsAdjustModalOpen(true);
                        }}
                        className="w-8 h-8 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center hover:bg-blue-600 hover:text-white transition-all shadow-sm"
                        title="Add Stock"
                      >
                        <Plus size={16} />
                      </button>
                      <button 
                        onClick={() => {
                          setSelectedProduct(product);
                          setAdjustmentType('REMOVE');
                          setIsAdjustModalOpen(true);
                        }}
                        className="w-8 h-8 rounded-lg bg-slate-50 text-slate-600 flex items-center justify-center hover:bg-slate-800 hover:text-white transition-all shadow-sm"
                        title="Remove Stock"
                      >
                        <ArrowDownLeft size={16} />
                      </button>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button className="text-slate-400 hover:text-slate-600 transition-colors">
                      <MoreVertical size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Stock Adjustment Modal */}
      {isAdjustModalOpen && selectedProduct && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsAdjustModalOpen(false)}></div>
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md relative z-10 overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50">
