        if (productIndex !== -1 && !isNaN(amount)) {
          const p = updatedProducts[productIndex];
          updatedProducts[productIndex] = {
            ...p,
            stock: Math.max(0, p.stock + amount)
          };
          successCount++;
        } else {
          errorCount++;
        }
      }

      setProducts(updatedProducts);
      setBulkStatus({ 
        success: `Successfully updated ${successCount} products.${errorCount > 0 ? ` Failed to process ${errorCount} rows.` : ''}` 
