import React, { useState, useRef } from 'react';
import { 
  Plus, 
  ArrowDownLeft, 
  ArrowUpRight, 
  Box, 
  AlertCircle, 
  Search,
  MoreVertical,
  Maximize2,
  Scan,
  Download,
  X,
  RefreshCw,
  History,
  FileUp,
  AlertOctagon,
  CheckCircle2,
  Clock,
  ArrowRight
} from 'lucide-react';
import { MOCK_PRODUCTS } from '../data/mockData';
import { Product, AdjustmentReason, StockCategory, StockLog } from '../types';

const Inventory: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'STOCK' | 'LOGS'>('STOCK');
  const [products, setProducts] = useState<Product[]>(MOCK_PRODUCTS);
  const [logs, setLogs] = useState<StockLog[]>([
    { id: 'l1', productId: '1', productName: 'AquaPure RO+UV 12L', type: 'ADD', quantity: 5, reason: AdjustmentReason.RESTOCK, timestamp: '2024-03-05 10:30 AM', user: 'Admin' },
    { id: 'l2', productId: '5', productName: 'Booster Pump 75 GPD', type: 'REMOVE', quantity: 2, reason: AdjustmentReason.DAMAGE, timestamp: '2024-03-04 02:15 PM', user: 'Staff' }
  ]);

  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [isAdjustModalOpen, setIsAdjustModalOpen] = useState(false);
  const [isBulkModalOpen, setIsBulkModalOpen] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  const [adjustmentType, setAdjustmentType] = useState<'ADD' | 'REMOVE'>('ADD');
  const [adjAmount, setAdjAmount] = useState<number>(0);
  const [adjReason, setAdjReason] = useState<AdjustmentReason>(AdjustmentReason.RESTOCK);
  const [searchTerm, setSearchTerm] = useState('');

  // Bulk import state
  const [bulkFile, setBulkFile] = useState<File | null>(null);
  const [bulkStatus, setBulkStatus] = useState<{ success?: string; error?: string }>({});
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleAdjustStock = () => {
    if (!selectedProduct || adjAmount <= 0) return;

    const updatedProducts = products.map(p => {
      if (p.id === selectedProduct.id) {
        const newStock = adjustmentType === 'ADD' 
          ? p.stock + adjAmount 
          : Math.max(0, p.stock - adjAmount);
        return { ...p, stock: newStock };
      }
      return p;
    });

    // Create log entry
    const newLog: StockLog = {
      id: `l${Date.now()}`,
      productId: selectedProduct.id,
      productName: selectedProduct.name,
      type: adjustmentType,
      quantity: adjAmount,
      reason: adjReason,
      timestamp: new Date().toLocaleString(),
      user: 'Admin'
    };

    setLogs([newLog, ...logs]);
    setProducts(updatedProducts);
    setIsAdjustModalOpen(false);
    setSelectedProduct(null);
    setAdjAmount(0);
  };

  const handleScanSimulation = () => {
    setIsScanning(true);
    setTimeout(() => {
      const randomProduct = products[Math.floor(Math.random() * products.length)];
      setSelectedProduct(randomProduct);
      setAdjustmentType('ADD');
      setIsScanning(false);
      setIsAdjustModalOpen(true);
    }, 1500);
  };

  const downloadTemplate = () => {
    const headers = 'productId,quantity,reason\n';
    const sampleRows = '1,10,RESTOCK\n2,-5,DAMAGE\n3,100,RESTOCK';
    const blob = new Blob([headers + sampleRows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'veera_inventory_bulk_template.csv';
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const processBulkImport = async () => {
    if (!bulkFile) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      const lines = text.split('\n');
      const updatedProducts = [...products];
      let successCount = 0;
      let errorCount = 0;

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        const [id, qty, reason] = line.split(',');
        const productIndex = updatedProducts.findIndex(p => p.id === id.trim());
        const amount = parseInt(qty?.trim());

        if (productIndex !== -1 && !isNaN(amount)) {
          const p = updatedProducts[productIndex];
          updatedProducts[productIndex] = {
            ...p,
            stock: Math.max(0, p.stock + amount)
          };
          successCount++;
        } else {
          errorCount++;
        }
      }

      setProducts(updatedProducts);
      setBulkStatus({ 
        success: `Successfully updated ${successCount} products.${errorCount > 0 ? ` Failed to process ${errorCount} rows.` : ''}` 
      });
      setTimeout(() => {
        setIsBulkModalOpen(false);
        setBulkFile(null);
        setBulkStatus({});
      }, 3000);
    };

    reader.onerror = () => setBulkStatus({ error: 'Failed to read file.' });
    reader.readAsText(bulkFile);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const lowStockCount = products.filter(p => p.stock <= p.lowStockThreshold).length;
  const outOfStockCount = products.filter(p => p.stock <= 0).length;
  const totalStockValue = products.reduce((acc, p) => acc + (p.stock * p.priceWholesale), 0);

  return (
    <div className="space-y-6">
      {/* Overview Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-blue-600 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
          <Box className="absolute -right-2 -bottom-2 opacity-10" size={80} />
          <p className="text-blue-100 text-xs font-bold uppercase tracking-wider mb-1">Total SKU</p>
          <p className="text-3xl font-black">{products.length}</p>
          <div className="mt-4 flex items-center gap-1 text-xs font-bold bg-blue-500/30 w-fit px-2 py-1 rounded-full">
            <Plus size={12} />
            Active Catalog
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">Wholesale Value</p>
          <p className="text-3xl font-black text-slate-900">₹{(totalStockValue / 100000).toFixed(2)}L</p>
          <p className="mt-4 text-xs font-medium text-emerald-600 flex items-center gap-1">
            <ArrowUpRight size={14} />
            Updated just now
          </p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">Low Stock</p>
          <p className="text-3xl font-black text-amber-500">{lowStockCount.toString().padStart(2, '0')}</p>
          <p className="mt-4 text-xs font-medium text-slate-500 flex items-center gap-1">
            <AlertCircle size={14} className="text-amber-500" />
            Requires Reorder
          </p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">Out of Stock</p>
          <p className="text-3xl font-black text-red-500">{outOfStockCount.toString().padStart(2, '0')}</p>
          <p className="mt-4 text-xs font-medium text-slate-500">Immediate Action</p>
        </div>
      </div>

      {/* Main Inventory Container */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex flex-col xl:flex-row xl:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <h3 className="font-bold text-lg">Inventory Tracking</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button 
                onClick={() => setActiveTab('STOCK')}
                className={`px-4 py-1.5 text-xs font-bold rounded shadow-sm transition-all ${
                  activeTab === 'STOCK' ? 'bg-white text-blue-600' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                Current Stock
              </button>
              <button 
                onClick={() => setActiveTab('LOGS')}
                className={`px-4 py-1.5 text-xs font-bold rounded transition-all ${
                  activeTab === 'LOGS' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                Audit Logs
              </button>
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            <div className="relative flex-1 sm:flex-none">
              <Search className="absolute left-3 top-2.5 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Search products..." 
                className="pl-10 pr-4 py-2 bg-slate-50 border-none rounded-xl text-sm w-full md:w-64 focus:ring-2 focus:ring-blue-500 outline-none"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <button 
              onClick={handleScanSimulation}
              disabled={isScanning}
              className={`px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all border ${
                isScanning ? 'bg-slate-200 text-slate-400 animate-pulse' : 'bg-slate-100 text-slate-700 hover:bg-slate-200 border-slate-200'
              }`}
            >
              <Scan size={18} />
              {isScanning ? 'Scanning...' : 'Scan'}
            </button>
            <button 
              onClick={() => setIsBulkModalOpen(true)}
              className="bg-slate-100 text-slate-700 px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-slate-200 transition-all border border-slate-200"
            >
              <Download size={18} />
              Bulk Import
            </button>
            <button className="bg-blue-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-blue-700 transition-all shadow-md active:scale-95">
              <Plus size={18} />
              Add Product
            </button>
          </div>
        </div>

        {activeTab === 'STOCK' ? (
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left">
              <thead className="bg-slate-50 border-b border-slate-100">
                <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                  <th className="px-6 py-4">Item Name</th>
                  <th className="px-6 py-4">Category</th>
                  <th className="px-6 py-4">Stock Levels</th>
                  <th className="px-6 py-4">Prices (R | W)</th>
                  <th className="px-6 py-4">Status</th>
                  <th className="px-6 py-4"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredProducts.map(product => (
                  <tr key={product.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <p className="font-bold text-slate-900 text-sm">{product.name}</p>
                      <p className="text-xs text-slate-400">SKU: VE-{product.id}00X</p>
                    </td>
                    <td className="px-6 py-4">
                      <span className="px-2 py-1 bg-slate-100 text-slate-600 rounded text-[10px] font-bold uppercase tracking-tighter">
                        {product.category}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-4 group/stock">
                        <div className="flex flex-col">
                          <div className="flex items-center gap-1.5">
                            <span className={`font-black text-lg leading-none ${product.stock <= product.lowStockThreshold ? 'text-amber-500' : 'text-slate-900'}`}>
                              {product.stock}
                            </span>
                            <span className="text-[10px] font-bold text-slate-400 uppercase">pcs</span>
                          </div>
                        </div>
                        <div className="flex gap-1">
                          <button 
                            onClick={() => {
                              setSelectedProduct(product);
                              setAdjustmentType('ADD');
                              setIsAdjustModalOpen(true);
                            }}
                            className="w-7 h-7 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center hover:bg-blue-600 hover:text-white transition-all shadow-sm active:scale-90"
                            title="Stock In (+)"
                          >
                            <Plus size={14} strokeWidth={3} />
                          </button>
                          <button 
                            onClick={() => {
                              setSelectedProduct(product);
                              setAdjustmentType('REMOVE');
                              setIsAdjustModalOpen(true);
                            }}
                            className="w-7 h-7 rounded-lg bg-slate-100 text-slate-600 flex items-center justify-center hover:bg-slate-800 hover:text-white transition-all shadow-sm active:scale-90"
                            title="Stock Out (-)"
                          >
                            <ArrowDownLeft size={14} strokeWidth={3} />
                          </button>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-xs">
                        <p className="font-bold text-slate-800">₹{product.priceRetail.toLocaleString()}</p>
                        <p className="text-slate-400">₹{product.priceWholesale.toLocaleString()}</p>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${
                        product.stock <= 0 ? 'bg-red-50 text-red-600' :
                        product.stock <= product.lowStockThreshold ? 'bg-amber-50 text-amber-600' :
                        'bg-emerald-50 text-emerald-600'
                      }`}>
                        {product.stock <= 0 ? 'Out of Stock' :
                         product.stock <= product.lowStockThreshold ? 'Low Stock' : 'Healthy'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button className="text-slate-400 hover:text-slate-600 transition-colors">
                        <MoreVertical size={18} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left">
              <thead className="bg-slate-50 border-b border-slate-100">
                <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                  <th className="px-6 py-4">Timestamp</th>
                  <th className="px-6 py-4">Product</th>
                  <th className="px-6 py-4">Type</th>
                  <th className="px-6 py-4">Quantity</th>
                  <th className="px-6 py-4">Reason</th>
                  <th className="px-6 py-4">By</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {logs.map(log => (
                  <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 text-xs text-slate-500">
                      <div className="flex items-center gap-2">
                        <Clock size={14} />
                        {log.timestamp}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <p className="font-bold text-slate-900 text-sm">{log.productName}</p>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1 px-2 py-1 rounded text-[10px] font-bold uppercase ${
                        log.type === 'ADD' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'
                      }`}>
                        {log.type === 'ADD' ? <ArrowUpRight size={10} /> : <ArrowDownLeft size={10} />}
                        Stock {log.type === 'ADD' ? 'In' : 'Out'}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <p className={`font-black text-sm ${log.type === 'ADD' ? 'text-emerald-600' : 'text-red-600'}`}>
                        {log.type === 'ADD' ? '+' : '-'}{log.quantity}
                      </p>
                    </td>
                    <td className="px-6 py-4">
                      <span className="px-2 py-1 bg-slate-100 text-slate-600 rounded text-[10px] font-bold uppercase">
                        {log.reason}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-xs font-bold text-slate-700">{log.user}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Stock Adjustment Modal */}
      {isAdjustModalOpen && selectedProduct && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => { setIsAdjustModalOpen(false); setSelectedProduct(null); }}></div>
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md relative z-10 overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50">
              <div>
                <h4 className="font-bold text-lg text-slate-900">Stock Adjustment</h4>
                <p className="text-xs text-slate-500">{selectedProduct.name}</p>
              </div>
              <button onClick={() => { setIsAdjustModalOpen(false); setSelectedProduct(null); }} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                <X size={20} />
              </button>
            </div>

            <div className="p-6 space-y-5">
              <div className="flex bg-slate-100 p-1.5 rounded-2xl">
                <button 
                  onClick={() => setAdjustmentType('ADD')}
                  className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${
                    adjustmentType === 'ADD' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  <ArrowUpRight size={18} />
                  Stock In
                </button>
                <button 
                  onClick={() => setAdjustmentType('REMOVE')}
                  className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${
                    adjustmentType === 'REMOVE' ? 'bg-white text-red-600 shadow-md' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  <ArrowDownLeft size={18} />
                  Stock Out
                </button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Current Stock</label>
                  <div className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-3 font-bold text-slate-500">
                    {selectedProduct.stock} pcs
                  </div>
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Quantity</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-xl px-4 py-3 font-bold focus:ring-0 outline-none"
                    placeholder="0"
                    autoFocus
                    value={adjAmount || ''}
                    onChange={(e) => setAdjAmount(Number(e.target.value))}
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Adjustment Reason</label>
                <select 
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-xl px-4 py-3 font-bold focus:ring-0 outline-none appearance-none"
                  value={adjReason}
                  onChange={(e) => setAdjReason(e.target.value as AdjustmentReason)}
                >
                  {Object.values(AdjustmentReason).map(reason => (
                    <option key={reason} value={reason}>{reason}</option>
                  ))}
                </select>
              </div>

              <button 
                onClick={handleAdjustStock}
                className={`w-full py-4 rounded-2xl font-black text-white shadow-lg transition-all active:scale-95 ${
                  adjustmentType === 'ADD' ? 'bg-blue-600 shadow-blue-200 hover:bg-blue-700' : 'bg-slate-900 shadow-slate-200 hover:bg-black'
                }`}
              >
                Confirm {adjustmentType === 'ADD' ? 'Inflow' : 'Outflow'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Bulk Import Modal */}
      {isBulkModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsBulkModalOpen(false)}></div>
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg relative z-10 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white">
                  <FileUp size={24} />
                </div>
                <div>
                  <h4 className="font-bold text-lg text-slate-900">Bulk Inventory Update</h4>
                  <p className="text-xs text-slate-500">Update stock using a CSV file</p>
                </div>
              </div>
              <button onClick={() => setIsBulkModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                <X size={20} />
              </button>
            </div>

            <div className="p-8 space-y-6">
              <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="text-blue-600">
                    <Download size={20} />
                  </div>
                  <div>
                    <p className="text-sm font-bold text-blue-900">Need a CSV template?</p>
                    <p className="text-xs text-blue-700">Download the required format</p>
                  </div>
                </div>
                <button 
                  onClick={downloadTemplate}
                  className="bg-white text-blue-600 px-4 py-2 rounded-xl text-xs font-bold hover:bg-blue-600 hover:text-white transition-all shadow-sm"
                >
                  Download
                </button>
              </div>

              <div 
                onClick={() => fileInputRef.current?.click()}
                className={`border-2 border-dashed rounded-3xl p-10 flex flex-col items-center justify-center gap-4 cursor-pointer transition-all ${
                  bulkFile ? 'border-blue-500 bg-blue-50/30' : 'border-slate-200 hover:border-blue-400 hover:bg-slate-50'
                }`}
              >
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  className="hidden" 
                  accept=".csv"
                  onChange={(e) => setBulkFile(e.target.files?.[0] || null)}
                />
                <div className={`p-4 rounded-2xl ${bulkFile ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>
                  <FileUp size={32} />
                </div>
                <div className="text-center">
                  <p className="font-bold text-slate-900">{bulkFile ? bulkFile.name : 'Choose CSV File'}</p>
                  <p className="text-xs text-slate-500 mt-1">or drag and drop file here</p>
                </div>
              </div>

              {bulkStatus.success && (
                <div className="flex items-center gap-3 p-4 bg-emerald-50 border border-emerald-100 rounded-2xl text-emerald-700 animate-in fade-in slide-in-from-top-2">
                  <CheckCircle2 size={20} />
                  <p className="text-sm font-medium">{bulkStatus.success}</p>
                </div>
              )}
              {bulkStatus.error && (
                <div className="flex items-center gap-3 p-4 bg-red-50 border border-red-100 rounded-2xl text-red-700 animate-in fade-in slide-in-from-top-2">
                  <AlertOctagon size={20} />
                  <p className="text-sm font-medium">{bulkStatus.error}</p>
                </div>
              )}

              <button 
                onClick={processBulkImport}
                disabled={!bulkFile || !!bulkStatus.success}
                className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black shadow-lg hover:bg-black transition-all active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Process Bulk Update
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

