// Placeholder pages for others
const ServicePage = () => <div className="p-8 text-center text-slate-500"><h2 className="text-2xl font-bold text-slate-800">Service & AMC Management</h2><p className="mt-2 italic">Module coming soon: Handle scheduling, renewals and logs.</p></div>;
const DealerPage = () => <div className="p-8 text-center text-slate-500"><h2 className="text-2xl font-bold text-slate-800">Wholesale & Dealer Hub</h2><p className="mt-2 italic">Module coming soon: Tracking bulk orders and regional sales.</p></div>;
const ReportsPage = () => <div className="p-8 text-center text-slate-500"><h2 className="text-2xl font-bold text-slate-800">Advanced Analytics</h2><p className="mt-2 italic">Module coming soon: Financial statements and sales trends.</p></div>;

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [products, setProducts] = useState<Product[]>(MOCK_PRODUCTS);
  const [stockLogs, setStockLogs] = useState<StockLog[]>([]);

  const updateProductStock = (productId: string, newStock: number, log?: Omit<StockLog, 'id' | 'timestamp' | 'productName' | 'productId'>) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    setProducts(prev => prev.map(p => p.id === productId ? { ...p, stock: newStock } : p));

    if (log) {
      const newLog: StockLog = {
        ...log,
        id: `l${Date.now()}`,
        productId: product.id,
        productName: product.name,
        timestamp: new Date().toLocaleString(),
      };
      setStockLogs(prev => [newLog, ...prev]);
    }
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'dashboard': 
        return <Dashboard products={products} />;
      case 'billing': 
        return <Billing products={products} onBillFinalized={(items) => {
          items.forEach(item => {
            const product = products.find(p => p.id === item.productId);
            if (product) {
              updateProductStock(product.id, product.stock - item.quantity);
            }
          });
        }} />;
      case 'customers': 
        return <Customers />;
      case 'inventory': 
        return (
          <Inventory 
            products={products} 
            setProducts={setProducts} 
            logs={stockLogs} 
            setLogs={setStockLogs} 
          />
        );
      case 'service': return <ServicePage />;
      case 'dealers': return <DealerPage />;
      case 'reports': return <ReportsPage />;
      default: return <Dashboard products={products} />;
    }
  };

  return (
    <Layout currentPage={currentPage} setCurrentPage={setCurrentPage}>
      {renderPage()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  Plus, 
  Trash2, 
  Search, 
  UserPlus, 
  Save, 
  Printer, 
  MessageSquare,
  ChevronDown,
  ShoppingBag,
  Ticket,
  Droplets,
  AlertCircle
} from 'lucide-react';
import { MOCK_CUSTOMERS } from '../data/mockData';
import { Product, InvoiceItem, PaymentMode } from '../types';

interface BillingProps {
  products: Product[];
  onBillFinalized: (items: InvoiceItem[]) => void;
}

const Billing: React.FC<BillingProps> = ({ products, onBillFinalized }) => {
  const [items, setItems] = useState<InvoiceItem[]>([]);
  const [discount, setDiscount] = useState(0);
  const [paymentMode, setPaymentMode] = useState<PaymentMode>(PaymentMode.UPI);
  const [customerSearch, setCustomerSearch] = useState('');
  const [productSearch, setProductSearch] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);

  const addItem = (product: Product) => {
    if (product.stock <= 0) return; // Simple safety check

    const existing = items.find(i => i.productId === product.id);
    if (existing) {
      if (existing.quantity >= product.stock) return; // Cannot exceed stock
      setItems(items.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + 1, total: (i.quantity + 1) * i.unitPrice } : i));
    } else {
      setItems([...items, {
        productId: product.id,
        name: product.name,
        quantity: 1,
        unitPrice: product.priceRetail,
        gstAmount: (product.priceRetail * product.gstRate) / 100,
        total: product.priceRetail
      }]);
    }
  };

  const removeItem = (id: string) => setItems(items.filter(i => i.productId !== id));

  const updateQuantity = (productId: string, delta: number) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    setItems(prev => prev.map(item => {
      if (item.productId === productId) {
        const newQty = Math.max(1, Math.min(product.stock, item.quantity + delta));
        return { ...item, quantity: newQty, total: newQty * item.unitPrice };
      }
      return item;
    }));
  };

  const subtotal = items.reduce((acc, curr) => acc + curr.total, 0);
  const gstTotal = items.reduce((acc, curr) => acc + (curr.gstAmount * curr.quantity), 0);
  const grandTotal = subtotal + gstTotal - discount;

  const handleFinalize = () => {
    if (items.length === 0) return;
    onBillFinalized(items);
    setItems([]);
    setIsSuccess(true);
    setTimeout(() => setIsSuccess(false), 3000);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(productSearch.toLowerCase()) || 
    p.category.toLowerCase().includes(productSearch.toLowerCase())
  );

  return (
    <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 h-full relative">
      {/* Left side: Item Selection & Current Bill */}
      <div className="xl:col-span-2 flex flex-col gap-6">
        {/* Customer & Product Selection */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex flex-wrap gap-4 mb-6">
            <div className="flex-1 min-w-[300px] relative">
              <Search className="absolute left-3 top-3 text-slate-400" size={20} />
              <input 
                type="text"
                placeholder="Find Customer by Name or Phone..."
                className="w-full pl-10 pr-4 py-2 bg-slate-50 border-none rounded-xl focus:ring-2 focus:ring-blue-500"
                value={customerSearch}
                onChange={(e) => setCustomerSearch(e.target.value)}
              />
            </div>
            <div className="flex-1 min-w-[300px] relative">
              <Search className="absolute left-3 top-3 text-slate-400" size={20} />
              <input 
                type="text"
                placeholder="Quick add product..."
                className="w-full pl-10 pr-4 py-2 bg-slate-50 border-none rounded-xl focus:ring-2 focus:ring-blue-500"
                value={productSearch}
                onChange={(e) => setProductSearch(e.target.value)}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
            {filteredProducts.slice(0, 8).map(product => (
              <button 
                key={product.id}
                onClick={() => addItem(product)}
                disabled={product.stock <= 0}
                className={`p-3 rounded-xl border border-transparent transition-all text-left relative overflow-hidden group ${
                  product.stock <= 0 
                    ? 'bg-slate-50 opacity-60 cursor-not-allowed' 
                    : 'bg-slate-50 hover:bg-blue-50 hover:border-blue-200'
                }`}
              >
                {product.stock <= product.lowStockThreshold && product.stock > 0 && (
                  <div className="absolute top-0 right-0 bg-amber-500 text-white text-[8px] px-1.5 py-0.5 rounded-bl-lg font-black uppercase">Low</div>
                )}
                {product.stock <= 0 && (
                  <div className="absolute inset-0 bg-slate-100/40 flex items-center justify-center backdrop-blur-[1px]">
                    <span className="text-[10px] font-black text-slate-400 uppercase rotate-12 border-2 border-slate-300 px-1">Sold Out</span>
                  </div>
                )}
                <p className="text-[10px] font-bold text-blue-600 mb-1">{product.category}</p>
                <p className="text-sm font-semibold truncate mb-1">{product.name}</p>
                <div className="flex items-center justify-between mt-2">
                  <p className="text-xs font-black">₹{product.priceRetail}</p>
                  <p className={`text-[10px] font-bold ${product.stock <= product.lowStockThreshold ? 'text-amber-600' : 'text-slate-400'}`}>
                    Stock: {product.stock}
                  </p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Invoice Items Table */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 flex-1 overflow-hidden flex flex-col">
          <div className="p-6 border-b border-slate-100 flex items-center justify-between">
            <h3 className="font-bold text-lg">Billing Items</h3>
            <span className="text-sm text-slate-500">{items.length} items added</span>
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <table className="w-full text-left">
              <thead className="bg-slate-50 sticky top-0 z-10">
                <tr className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                  <th className="px-6 py-3">Product Name</th>
                  <th className="px-6 py-3">Price</th>
                  <th className="px-6 py-3">Qty</th>
                  <th className="px-6 py-3">GST</th>
                  <th className="px-6 py-3">Total</th>
                  <th className="px-6 py-3"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {items.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                      <ShoppingBag size={48} className="mx-auto mb-4 opacity-20" />
                      <p>No items added to bill yet</p>
                    </td>
                  </tr>
                ) : (
                  items.map((item, idx) => (
                    <tr key={idx} className="hover:bg-slate-50">
                      <td className="px-6 py-4 font-medium text-sm">{item.name}</td>
                      <td className="px-6 py-4 text-sm">₹{item.unitPrice}</td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <button 
                            onClick={() => updateQuantity(item.productId, -1)}
                            className="w-6 h-6 flex items-center justify-center rounded bg-slate-100 text-slate-600 hover:bg-slate-200"
                          >-</button>
                          <span className="w-8 text-center text-sm font-bold">{item.quantity}</span>
                          <button 
                            onClick={() => updateQuantity(item.productId, 1)}
                            className="w-6 h-6 flex items-center justify-center rounded bg-slate-100 text-slate-600 hover:bg-slate-200"
                          >+</button>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-sm text-slate-500">₹{item.gstAmount}</td>
                      <td className="px-6 py-4 text-sm font-bold">₹{item.total}</td>
                      <td className="px-6 py-4">
                        <button 
                          onClick={() => removeItem(item.productId)}
                          className="text-red-400 hover:text-red-600 p-1"
                        >
                          <Trash2 size={18} />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Right side: Payment & Summary */}
      <div className="flex flex-col gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 sticky top-6">
          <h3 className="font-bold text-lg mb-6 flex items-center gap-2">
            <Ticket className="text-blue-600" size={20} />
            Summary
          </h3>

          <div className="space-y-4 mb-6">
            <div className="flex justify-between text-slate-600">
              <span>Subtotal</span>
              <span>₹{subtotal.toFixed(2)}</span>
            </div>
            <div className="flex justify-between text-slate-600">
              <span>GST Total</span>
              <span>₹{gstTotal.toFixed(2)}</span>
            </div>
            <div className="flex justify-between items-center text-slate-600">
              <span>Discount</span>
              <div className="relative w-32">
                <span className="absolute left-2 top-1.5 text-xs">₹</span>
                <input 
                  type="number"
                  className="w-full pl-5 pr-2 py-1 bg-slate-50 border-none rounded text-right text-sm font-bold"
                  value={discount}
                  onChange={(e) => setDiscount(Number(e.target.value))}
                />
              </div>
            </div>
            <div className="h-px bg-slate-100 my-4"></div>
            <div className="flex justify-between items-end">
              <span className="font-bold text-lg">Total Amount</span>
              <span className="font-black text-2xl text-blue-600">₹{grandTotal.toFixed(2)}</span>
            </div>
          </div>

          <div className="mb-6">
            <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Payment Method</p>
            <div className="grid grid-cols-3 gap-2">
              {Object.values(PaymentMode).slice(0, 3).map((mode) => (
                <button
                  key={mode}
                  onClick={() => setPaymentMode(mode)}
                  className={`py-2 px-1 text-xs font-bold rounded-lg border-2 transition-all ${
                    paymentMode === mode 
                      ? 'bg-blue-600 text-white border-blue-600' 
                      : 'bg-white text-slate-600 border-slate-100 hover:border-blue-200'
                  }`}
                >
                  {mode}
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-3">
            <button 
              onClick={handleFinalize}
              disabled={items.length === 0}
              className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-200 active:scale-[0.98] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Save size={20} />
              Finalize & Save Bill
            </button>
            <div className="grid grid-cols-2 gap-3">
              <button className="bg-slate-100 text-slate-700 py-3 rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-slate-200 transition-all">
                <Printer size={18} />
                Print
              </button>
              <button className="bg-emerald-50 text-emerald-600 py-3 rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-emerald-100 transition-all">
                <MessageSquare size={18} />
                WhatsApp
              </button>
            </div>
          </div>
        </div>

        {/* Shortcuts / Quick Info */}
        <div className="bg-slate-900 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
          <Droplets className="absolute -right-4 -bottom-4 text-white opacity-10" size={120} />
          <p className="text-blue-400 font-bold text-xs uppercase mb-2">Billing Tip</p>
          <p className="text-sm text-slate-300 leading-relaxed mb-4">
            Enable <strong>Wholesale Mode</strong> from settings to auto-apply dealer pricing for specific customer types.
          </p>
          <button className="text-white font-bold text-sm underline underline-offset-4 hover:text-blue-300 transition-colors">
            Manage Dealer Pricing
          </button>
        </div>
      </div>

      {/* Success Notification */}
      {isSuccess && (
        <div className="fixed top-20 right-10 bg-emerald-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-right-8 duration-300 z-50">
          <div className="w-8 h-8 bg-white/20 rounded-full flex items-center justify-center">
            <Plus size={18} className="rotate-45" />
          </div>
          <div>
            <p className="font-bold text-sm">Bill Generated Successfully!</p>
            <p className="text-[10px] opacity-80 uppercase font-bold">Inventory levels updated in real-time</p>
          </div>
        </div>
      )}
    </div>
  );
};

