import React, { useState, useRef } from 'react';
import { 
  Plus, 
  ArrowDownLeft, 
  ArrowUpRight, 
  Box, 
  AlertCircle, 
  Search,
  MoreVertical,
  Maximize2,
  Scan,
  Download,
  X,
  RefreshCw,
  History,
  FileUp,
  AlertOctagon,
  CheckCircle2,
  Clock,
  ArrowRight
} from 'lucide-react';
import { Product, AdjustmentReason, StockCategory, StockLog } from '../types';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  logs: StockLog[];
  setLogs: React.Dispatch<React.SetStateAction<StockLog[]>>;
}

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, logs, setLogs }) => {
  const [activeTab, setActiveTab] = useState<'STOCK' | 'LOGS'>('STOCK');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [isAdjustModalOpen, setIsAdjustModalOpen] = useState(false);
  const [isBulkModalOpen, setIsBulkModalOpen] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  const [adjustmentType, setAdjustmentType] = useState<'ADD' | 'REMOVE'>('ADD');
  const [adjAmount, setAdjAmount] = useState<number>(0);
  const [adjReason, setAdjReason] = useState<AdjustmentReason>(AdjustmentReason.RESTOCK);
  const [searchTerm, setSearchTerm] = useState('');

  // Bulk import state
  const [bulkFile, setBulkFile] = useState<File | null>(null);
  const [bulkStatus, setBulkStatus] = useState<{ success?: string; error?: string }>({});
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleAdjustStock = () => {
    if (!selectedProduct || adjAmount <= 0) return;

    const updatedProducts = products.map(p => {
      if (p.id === selectedProduct.id) {
        const newStock = adjustmentType === 'ADD' 
          ? p.stock + adjAmount 
          : Math.max(0, p.stock - adjAmount);
        return { ...p, stock: newStock };
      }
      return p;
    });

    // Create log entry
    const newLog: StockLog = {
      id: `l${Date.now()}`,
      productId: selectedProduct.id,
      productName: selectedProduct.name,
      type: adjustmentType,
      quantity: adjAmount,
      reason: adjReason,
      timestamp: new Date().toLocaleString(),
      user: 'Admin'
    };

    setLogs([newLog, ...logs]);
    setProducts(updatedProducts);
    setIsAdjustModalOpen(false);
    setSelectedProduct(null);
    setAdjAmount(0);
  };

  const handleScanSimulation = () => {
    setIsScanning(true);
    setTimeout(() => {
      const randomProduct = products[Math.floor(Math.random() * products.length)];
      setSelectedProduct(randomProduct);
      setAdjustmentType('ADD');
      setIsScanning(false);
      setIsAdjustModalOpen(true);
    }, 1500);
  };

  const downloadTemplate = () => {
    const headers = 'productId,quantity,reason\n';
    const sampleRows = '1,10,RESTOCK\n2,-5,DAMAGE\n3,100,RESTOCK';
    const blob = new Blob([headers + sampleRows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'veera_inventory_bulk_template.csv';
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const processBulkImport = async () => {
    if (!bulkFile) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      const lines = text.split('\n');
      const updatedProducts = [...products];
      let successCount = 0;
      let errorCount = 0;
      const newLogs: StockLog[] = [];

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        const [id, qty, reason] = line.split(',');
        const productIndex = updatedProducts.findIndex(p => p.id === id.trim());
        const amount = parseInt(qty?.trim());

        if (productIndex !== -1 && !isNaN(amount)) {
          const p = updatedProducts[productIndex];
          updatedProducts[productIndex] = {
            ...p,
            stock: Math.max(0, p.stock + amount)
          };

          newLogs.push({
            id: `l${Date.now()}-${successCount}`,
            productId: p.id,
            productName: p.name,
            type: amount >= 0 ? 'ADD' : 'REMOVE',
            quantity: Math.abs(amount),
            reason: (reason?.trim() as AdjustmentReason) || AdjustmentReason.RESTOCK,
            timestamp: new Date().toLocaleString(),
            user: 'Admin (Bulk)'
          });

          successCount++;
        } else {
          errorCount++;
        }
      }

      setProducts(updatedProducts);
      setLogs(prev => [...newLogs, ...prev]);
      setBulkStatus({ 
        success: `Successfully updated ${successCount} products.${errorCount > 0 ? ` Failed to process ${errorCount} rows.` : ''}` 
      });
      setTimeout(() => {
        setIsBulkModalOpen(false);
        setBulkFile(null);
        setBulkStatus({});
      }, 3000);
    };

    reader.onerror = () => setBulkStatus({ error: 'Failed to read file.' });
    reader.readAsText(bulkFile);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const lowStockCount = products.filter(p => p.stock <= p.lowStockThreshold).length;
  const outOfStockCount = products.filter(p => p.stock <= 0).length;
  const totalStockValue = products.reduce((acc, p) => acc + (p.stock * p.priceWholesale), 0);

  return (
    <div className="space-y-6">
      {/* Overview Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-blue-600 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
          <Box className="absolute -right-2 -bottom-2 opacity-10" size={80} />
          <p className="text-blue-100 text-xs font-bold uppercase tracking-wider mb-1">Total SKU</p>
          <p className="text-3xl font-black">{products.length}</p>
          <div className="mt-4 flex items-center gap-1 text-xs font-bold bg-blue-500/30 w-fit px-2 py-1 rounded-full">
            <Plus size={12} />
            Active Catalog
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">Wholesale Value</p>
          <p className="text-3xl font-black text-slate-900">₹{(totalStockValue / 100000).toFixed(2)}L</p>
          <p className="mt-4 text-xs font-medium text-emerald-600 flex items-center gap-1">
            <ArrowUpRight size={14} />
            Updated just now
          </p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">Low Stock</p>
          <p className="text-3xl font-black text-amber-500">{lowStockCount.toString().padStart(2, '0')}</p>
          <p className="mt-4 text-xs font-medium text-slate-500 flex items-center gap-1">
            <AlertCircle size={14} className="text-amber-500" />
            Requires Reorder
          </p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">Out of Stock</p>
          <p className="text-3xl font-black text-red-500">{outOfStockCount.toString().padStart(2, '0')}</p>
          <p className="mt-4 text-xs font-medium text-slate-500">Immediate Action</p>
        </div>
      </div>

      {/* Main Inventory Container */}
