    return saved ? JSON.parse(saved) : MOCK_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('veera_customers');
    return saved ? JSON.parse(saved) : MOCK_CUSTOMERS;
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('veera_invoices');
    return saved ? JSON.parse(saved) : MOCK_INVOICES;
  });

  const [stockLogs, setStockLogs] = useState<StockLog[]>(() => {
    const saved = localStorage.getItem('veera_stock_logs');
    return saved ? JSON.parse(saved) : [];
  });

  const [serviceRecords, setServiceRecords] = useState<ServiceRecord[]>(() => {
    const saved = localStorage.getItem('veera_service_records');
    return saved ? JSON.parse(saved) : [
      { id: 's1', customerId: 'c4', customerName: 'Dr. Deshpande Clinic', date: '2024-03-01', type: 'SERVICE', description: 'Regular Filter Replacement', technician: 'Rahul S.', cost: 850, status: 'COMPLETED', nextServiceDueDate: '2024-09-01' }
    ];
  });

  useEffect(() => {
    localStorage.setItem('veera_settings', JSON.stringify(settings));
    localStorage.setItem('veera_products', JSON.stringify(products));
    localStorage.setItem('veera_customers', JSON.stringify(customers));
    localStorage.setItem('veera_invoices', JSON.stringify(invoices));
    localStorage.setItem('veera_stock_logs', JSON.stringify(stockLogs));
    localStorage.setItem('veera_service_records', JSON.stringify(serviceRecords));
  }, [settings, products, customers, invoices, stockLogs, serviceRecords]);

  const handleLogin = (role: UserRole) => {
    setUserRole(role);
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
  };

  const handleReset = () => {
    localStorage.clear();
    window.location.reload();
  };

  const updateProductStock = (productId: string, newStock: number, log?: Omit<StockLog, 'id' | 'timestamp' | 'productName' | 'productId'>) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    setProducts(prev => prev.map(p => p.id === productId ? { ...p, stock: newStock } : p));
    if (log) {
      const newLog: StockLog = { ...log, id: `l${Date.now()}`, productId: product.id, productName: product.name, timestamp: new Date().toLocaleString() };
      setStockLogs(prev => [newLog, ...prev]);
    }
  };

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} />;
  }

  const renderPage = () => {
    switch (currentPage) {
      case 'dashboard': 
        return <Dashboard products={products} invoices={invoices} customers={customers} setCurrentPage={setCurrentPage} />;
      case 'billing': 
        return <Billing 
          products={products} 
          customers={customers}
          onBillFinalized={(newInvoice) => {
            setInvoices(prev => [newInvoice, ...prev]);
            newInvoice.items.forEach(item => {
              const p = products.find(prod => prod.id === item.productId);
              if (p) updateProductStock(p.id, p.stock - item.quantity);
            });
            setCustomers(prev => prev.map(c => c.id === newInvoice.customerId ? { ...c, totalPurchase: c.totalPurchase + newInvoice.grandTotal } : c));
          }} 
        />;
      case 'customers': 
        return <Customers customers={customers} setCustomers={setCustomers} />;
      case 'inventory': 
        return <Inventory products={products} setProducts={setProducts} logs={stockLogs} setLogs={setStockLogs} />;
      case 'service': 
        return <Service records={serviceRecords} setRecords={setServiceRecords} customers={customers} />;
      case 'dealers': 
        return <Dealers customers={customers} invoices={invoices} setCustomers={setCustomers} />;
      case 'reports': 
        return <Reports invoices={invoices} products={products} customers={customers} />;
      case 'settings':
        return <Settings settings={settings} setSettings={setSettings} onReset={handleReset} />;
      default: return <Dashboard products={products} invoices={invoices} customers={customers} setCurrentPage={setCurrentPage} />;
    }
  };

  return (
    <Layout currentPage={currentPage} setCurrentPage={setCurrentPage} onLogout={handleLogout} userRole={userRole}>
      {renderPage()}
    </Layout>
  );
};

export default App;
